// Existing signed Reality worker -> protected GitHub writer for a new Chat
// development candidate. This broker can only stage/read an inert proposal.
// Source code generated by a model never enters a live preview automatically.
const SHA=/^[a-f0-9]{40}$/;
const BRANCH=/^reality\/[A-Za-z0-9/_-]{10,160}$/;
const safe=(status,extra={})=>Object.freeze({
 status,source_installed:false,installation_authorized:false,
 original_job_completed:false,production_changed:false,
 new_shift_started:false,feature_acceptance_verified:false,...extra});
export async function continueChatNewDevelopmentCandidate({
 db,env=process.env,fetchImpl=fetch
}={}){
 if(env.VERCEL_ENV!=='preview'||!db?.strictSecrets||
   db.project!==env.REALITY_PERSONAL_CHAT_EXPECTED_PROJECT_REF||
   db.url!=='https://'+db.project+'.supabase.co'||
   typeof db.secretKey!=='string'||db.secretKey.length<24||
   !SHA.test(env.VERCEL_GIT_COMMIT_SHA||'')||
   !BRANCH.test(env.VERCEL_GIT_COMMIT_REF||'')||
   env.VERCEL_GIT_COMMIT_REF.includes('..')||
   env.VERCEL_GIT_COMMIT_REF.includes('//')||
   env.VERCEL_GIT_COMMIT_REF.startsWith('reality/chat-development/')||
   env.VERCEL_GIT_COMMIT_REF.startsWith('reality/riley/')||
   typeof fetchImpl!=='function')
  return safe('CHAT_NEW_DEV_PROVIDER_PREVIEW_BOUNDARY_UNVERIFIED');
 let response,result;
 try{
  response=await fetchImpl(db.url+
   '/functions/v1/reality-chat-new-development-broker-v1',{
   method:'POST',cache:'no-store',redirect:'error',
   signal:AbortSignal.timeout(45000),
   headers:{apikey:db.secretKey,authorization:'Bearer '+db.secretKey,
    accept:'application/json','content-type':'application/json'},
   body:JSON.stringify({
    action:'stage_or_verify_chat_new_development',
    base_branch:env.VERCEL_GIT_COMMIT_REF,
    base_sha:env.VERCEL_GIT_COMMIT_SHA})
  });
  result=await response.json();
 }catch{return safe('CHAT_NEW_DEV_PROVIDER_EFFECT_UNVERIFIED_NO_REPLAY')}
 if(!result||Array.isArray(result)||typeof result!=='object'||
   result.source_installed!==false||
   result.installation_authorized!==false||
   result.original_job_completed!==false||
   result.production_changed!==false||
   result.new_shift_started!==false||
   result.feature_acceptance_verified!==false||
   typeof result.status!=='string'||
   !/^[A-Z][A-Z0-9_]{9,130}$/.test(result.status))
  return safe('CHAT_NEW_DEV_PROVIDER_RESPONSE_UNTRUSTED');
 if(!response.ok)
  return safe('CHAT_NEW_DEV_PROVIDER_OR_DATABASE_UNVERIFIED');
 if(result.original_work_id!=null&&
    !/^work:[a-f0-9]{32}$/.test(result.original_work_id))
  return safe('CHAT_NEW_DEV_PROVIDER_ORIGINAL_IDENTITY_INVALID');
 if(result.artifact_commit_sha!=null&&!SHA.test(result.artifact_commit_sha))
  return safe('CHAT_NEW_DEV_PROVIDER_ARTIFACT_IDENTITY_INVALID');
 if(result.pr_url!=null&&
   !/^https:\/\/github\.com\/maloney2323\/Reality\/pull\/[1-9]\d*$/.test(result.pr_url))
  return safe('CHAT_NEW_DEV_PROVIDER_PR_URL_INVALID');
 if(result.ci_run_id!=null&&
   (!Number.isSafeInteger(result.ci_run_id)||result.ci_run_id<10000))
  return safe('CHAT_NEW_DEV_PROVIDER_CI_RUN_ID_INVALID');
 return safe(result.status,{
  ...(result.original_work_id?{original_work_id:result.original_work_id}:{}),
  ...(result.artifact_commit_sha?{artifact_commit_sha:result.artifact_commit_sha}:{}),
  ...(result.pr_url?{pr_url:result.pr_url}:{}),
  ...(result.ci_run_id?{ci_run_id:result.ci_run_id}:{}),
  independent_ci_verified:result.independent_ci_verified===true,
  ci_scope:result.ci_scope||null,
  model_generated:result.model_generated===true});
}
